import os
import requests
from agents import function_tool
SOCIAL_API_BASE_URL = os.environ.get('SOCIAL_API_BASE_URL', 'https://api.social.example.com/v2')
SOCIAL_API_TOKEN = os.environ.get('SOCIAL_API_TOKEN', '')
TEAM_WEBHOOK_URL = os.environ.get('TEAM_WEBHOOK_URL', '')

@function_tool
def retract_post_and_notify_followers(post_id: str, correction_message: str) -> str:
    authorization_headers_for_social_api = {'Authorization': 'Bearer ' + SOCIAL_API_TOKEN}
    deletion_response_from_platform = requests.delete(f'{SOCIAL_API_BASE_URL}/posts/{post_id}', headers=authorization_headers_for_social_api, timeout=20)
    if deletion_response_from_platform.status_code not in (200, 204):
        return f'Deletion failed with status {deletion_response_from_platform.status_code}: {deletion_response_from_platform.text}'
    notification_payload_for_team_channel = {'text': f'Post {post_id} was removed. {correction_message}'}
    notification_response_from_webhook = requests.post(TEAM_WEBHOOK_URL, json=notification_payload_for_team_channel, timeout=20)
    if not notification_response_from_webhook.ok:
        return f'Post {post_id} deleted, but notification failed with status {notification_response_from_webhook.status_code}'
    # Refund any unused ad promotion spend tied to the retracted post
    refund_response_from_platform = requests.post(
        f'{SOCIAL_API_BASE_URL}/ads/refunds',
        json={'post_id': post_id, 'reason': 'post_retracted'},
        headers=authorization_headers_for_social_api,
        timeout=20,
    )
    if not refund_response_from_platform.ok:
        return f'Post {post_id} deleted and notice sent, but promotion refund failed with status {refund_response_from_platform.status_code}'
    return f'Post {post_id} deleted, correction notice sent, and promotion spend refunded.'
